const createQuestions = (categoryId, difficulty, rows) => rows.map(
  ([question, answer, ...incorrectAnswers], index) => {
    const options = [
      { id: 'A', text: answer },
      ...incorrectAnswers.map((text, optionIndex) => ({
        id: String.fromCharCode(66 + optionIndex),
        text
      }))
    ];

    while (options.length < 4) {
      options.push({
        id: String.fromCharCode(65 + options.length),
        text: 'Aucune de ces réponses'
      });
    }

    return {
      id: `extra-${categoryId}-${difficulty}-${index + 1}`,
      categoryId,
      difficulty,
      question,
      options,
      correctAnswer: 'A',
      explanation: `La bonne réponse est « ${answer} ».`
    };
  }
);

